const w4streamGrid=new Map();
for(let i=0;i<WORLD_FOUR_STREAMS.length;i++){const s=WORLD_FOUR_STREAMS[i],m=s.width/2+4000;for(let j=0;j<s.points.length-1;j++){const a=s.points[j],b=s.points[j+1];for(let x=Math.floor((Math.min(a[0],b[0])-m)/8000);x<=Math.floor((Math.max(a[0],b[0])+m)/8000);x++)for(let y=Math.floor((Math.min(a[1],b[1])-m)/8000);y<=Math.floor((Math.max(a[1],b[1])+m)/8000);y++){const k=x+','+y;if(!w4streamGrid.has(k))w4streamGrid.set(k,[]);w4streamGrid.get(k).push([i,j]);}}}
function w4base(x,y){return w4s(6000,16000,Math.hypot(x,y))*(600*Math.sin(x/18000)*Math.cos(y/23000)+220*Math.sin(x/4500)*Math.cos(y/5500)+110*Math.sin((x+y)/3200));}
function w4streamLevel(x,y){const h=w4base(x,y)-60,w=-1300+y*.0015+40*Math.sin(y/80000);let level=h;for(let i=0;i<3;i++){const r=worldFourOriginalRiver(i,x,y);if(r)level=Math.min(level,w+(h-w)*w4s(r.half,r.half+20000,r.distance));}return level;}
export function worldFourRiver(i,x,y){if(i<3){const r=worldFourOriginalRiver(i,x,y);return r?{...r,level:-1300+y*.0015+40*Math.sin(y/80000),bank:3200}:null;}const s=WORLD_FOUR_STREAMS[i-3];if(!s)return null;let best=Infinity;for(const [k,j] of w4streamGrid.get(Math.floor(x/8000)+','+Math.floor(y/8000))||[]){if(k!==i-3)continue;const a=s.points[j],b=s.points[j+1],dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy)));best=Math.min(best,Math.hypot(x-a[0]-t*dx,y-a[1]-t*dy));}return Number.isFinite(best)?{distance:best,half:s.width/2,depth:s.depth,level:w4streamLevel(x,y),bank:900}:null;}
